def packaged_cli() -> Path:
    cli_name = "domainry-cli.exe" if os.name == "nt" else "domainry-cli"
    cli = Path(__file__).resolve().parent / cli_name
    if cli.is_symlink() or not cli.is_file() or (os.name != "nt" and not os.access(cli, os.X_OK)):
        raise GateError("Runtime Gate profile packaged CLI is unavailable or unsafe")
    return cli


def runtime_profile_path(project: Path, session: str) -> Path:
    return project / ".domainry" / "builder" / "development-gates" / f"{session}.runtime-profile.json"


def runtime_profile_todo(session: str) -> str:
    return (
        "# Runtime-process continuation TODO\n\n"
        f"{RUNTIME_PROFILE_OWNER_MARKER}\n\n"
        f"Agent session ID: {session}\n\n"
        f"Profile: {RUNTIME_PROFILE}\n\n"
        "Current stage: runtime\n\n"
        "This minimal TODO is owned by the Gate runner. Execute only the remaining returned run recipes; do not edit, add, reorder, or rerun its Gates.\n\n"
        "## runtime\n\n"
        f"- [ ] {RUNTIME_PROFILE_LABELS[0]} <!-- domainry:gate-kind=runtime_start -->\n"
        "  - Evidence: pending\n"
        f"- [ ] {RUNTIME_PROFILE_LABELS[1]} <!-- domainry:gate-kind=runtime_status -->\n"
        "  - Evidence: pending\n"
    )


def normalized_runtime_profile_todo(content: str) -> str:
    lines = content.splitlines()
    starts = [index for index, line in enumerate(lines) if line == PROJECTION_START]
    ends = [index for index, line in enumerate(lines) if line == PROJECTION_END]
    if starts or ends:
        if len(starts) != 1 or len(ends) != 1 or starts[0] >= ends[0]:
            raise GateError("Runtime Gate profile TODO projection is unsafe")
        lines[starts[0]:ends[0] + 1] = []
    normalized = []
    blank = False
    for line in lines:
        checkbox = CHECKBOX.match(line)
        if checkbox:
            line = checkbox.group(1) + " " + checkbox.group(3) + checkbox.group(4)
        evidence = EVIDENCE_LINE.match(line)
        if evidence:
            line = evidence.group(1) + "pending"
        if not line.strip():
            if blank:
                continue
            blank = True
            normalized.append("")
        else:
            blank = False
            normalized.append(line)
    return "\n".join(normalized).strip() + "\n"


def validate_runtime_profile_todo(project: Path, session: str) -> list[dict]:
    path = todo_path(project, session)
    content = path.read_text(encoding="utf-8")
    if (
        content.count(RUNTIME_PROFILE_OWNER_MARKER) != 1
        or normalized_runtime_profile_todo(content)
        != normalized_runtime_profile_todo(runtime_profile_todo(session))
    ):
        raise GateError("Runtime Gate profile found a non-profile-owned or conflicting session TODO")
    discovered = discover_gates(content)
    if (
        [gate["label"] for gate in discovered] != list(RUNTIME_PROFILE_LABELS)
        or [gate["kind"] for gate in discovered] != ["runtime_start", "runtime_status"]
        or any(gate["stage"] != "runtime" for gate in discovered)
    ):
        raise GateError("Runtime Gate profile TODO Gate order, kind, or label differs")
    return discovered


def current_runtime_profile_inputs(project: Path, address: str) -> dict:
    if not loopback_address(address):
        raise GateError("Runtime Gate profile requires an explicit numeric loopback address")
    cli = packaged_cli()
    receipt_path = project / PACKAGE_RECEIPT
    manifest_path = project / RUNTIME_MANIFEST
    try:
        package, _ = bounded_project_json(project, PACKAGE_RECEIPT)
        verification, _ = bounded_project_json(project, VERIFICATION_RECEIPT)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError, GateError) as error:
        raise GateError("Runtime Gate profile requires the current package receipt") from error
    bundle = package.get("bundle_path") if isinstance(package, dict) else None
    if (
        package.get("contract_version") != PROJECT_PACKAGE_CONTRACT
        or verification.get("contract_version") != PROJECT_VERIFICATION_CONTRACT
        or not isinstance(bundle, str)
        or not bundle
        or Path(bundle).is_absolute()
        or ".." in Path(bundle).parts
        or "\\" in bundle
    ):
        raise GateError("Runtime Gate profile package receipt is invalid")
    bundle_path = project / bundle
    if bundle_path.is_symlink() or not bundle_path.is_dir():
        raise GateError("Runtime Gate profile bundle is unavailable or unsafe")
    if manifest_path.is_symlink() or not manifest_path.is_file():
        raise GateError("Runtime Gate profile requires the current package Runtime manifest")
    bundle_manifest = bundle_path / "manifest.json"
    if bundle_manifest.is_symlink() or not bundle_manifest.is_file():
        raise GateError("Runtime Gate profile bundle manifest is unavailable or unsafe")
    closure = (
        (delivery_sha(package, "verification_receipt_sha256"), delivery_sha(verification, "receipt_sha256")),
        (delivery_sha(package, "finalization_receipt_sha256"), delivery_sha(verification, "finalization_receipt_sha256")),
        (delivery_sha(package, "project_source_tree_sha256"), delivery_sha(verification, "project_source_tree_sha256")),
        (delivery_sha(verification, "runtime_manifest_sha256"), sha256_file(manifest_path)),
        (delivery_sha(package, "manifest_sha256"), sha256_file(bundle_manifest)),
    )
    if any(actual != expected for actual, expected in closure):
        raise GateError("Runtime Gate profile package/verification/bundle identity closure is stale")
    identity = identities(project)
    identity["runtime_manifest_sha"] = delivery_runtime_manifest_sha(project)
    require_available_bindings(identity, ["source", "runtime"])
    return {
        "address": address,
        "bundle": bundle,
        "cli": str(cli),
        "cli_sha256": sha256_file(cli),
        "package_receipt_sha256": sha256_file(receipt_path),
        "runtime_manifest_sha256": sha256_file(manifest_path),
        "source_sha256": identity["source_sha"],
    }


def runtime_profile_gates(project: Path, session: str, state: dict) -> list[dict]:
    validate_runtime_profile_todo(project, session)
    active = sorted(
        (gate for gate in state["gates"].values() if gate.get("active", True)),
        key=lambda gate: gate.get("todo_line", 0),
    )
    if (
        len(active) != 2
        or [gate.get("kind") for gate in active] != ["runtime_start", "runtime_status"]
        or [gate.get("label") for gate in active] != list(RUNTIME_PROFILE_LABELS)
    ):
        raise GateError(
            "Runtime Gate profile requires exactly one machine runtime_start Gate followed by runtime_status"
        )
    return active


def runtime_profile_recipes(project: Path, session: str, gates: list[dict]) -> list[dict]:
    runner = str(Path(__file__).resolve())
    base = [runner, "--project", str(project), "--session-id", session, "run-runtime-profile"]
    failed = any(
        gate.get("status") == "failed"
        or (terminal_command_receipt(project, session, gate["gate_id"]) or {}).get("runner_state") == "failed"
        for gate in gates
    )
    if failed:
        return []
    recipes = []
    for gate in gates:
        terminal = terminal_command_receipt(project, session, gate["gate_id"])
        if gate.get("status") == "passed" or (terminal or {}).get("runner_state") == "passed":
            continue
        recipes.append({
            "gate_id": gate["gate_id"],
            "gate_kind": gate["kind"],
            "argv": [*base, "--gate-kind", gate["kind"]],
        })
    return recipes


def command_init_runtime_profile(args, project: Path, session: str) -> int:
    todo = project / ".domainry" / "development" / f"{session}.md"
    state_file = state_path(project, session)
    path = runtime_profile_path(project, session)
    artifacts = (todo, state_file, path)
    present = [artifact.exists() or artifact.is_symlink() for artifact in artifacts]
    if any(present) and not all(present):
        raise GateError("Runtime Gate profile found a partial or conflicting session initialization")
    created = not any(present)
    if not created and any(
        artifact.is_symlink() or not artifact.is_file() for artifact in artifacts
    ):
        raise GateError("Runtime Gate profile session artifacts are unsafe")
    inputs = current_runtime_profile_inputs(project, args.address)

    try:
        if created:
            ensure_safe_directory(project, todo.parent)
            ensure_safe_directory(project, state_file.parent)
            atomic_text(todo, runtime_profile_todo(session))
        state = sync_gates(project, session, load_state(project, session))
        gates = runtime_profile_gates(project, session, state)
        profile = {
            "contract_version": RUNTIME_PROFILE_VERSION,
            "profile": RUNTIME_PROFILE,
            "project": str(project),
            "session_id": session,
            "gate_ids": {gate["kind"]: gate["gate_id"] for gate in gates},
            "bindings": ["source", "runtime", "runtime_cohort", "runtime_instance"],
            **inputs,
        }
        if created:
            state["runtime_profile"] = profile
            save(project, session, state)
            atomic_json(path, profile)
        else:
            existing = json.loads(path.read_text(encoding="utf-8"))
            if existing != profile or state.get("runtime_profile") != profile:
                raise GateError(
                    "Runtime Gate profile conflicts with the current package, source, address, CLI, or Gate identity"
                )
            save(project, session, state)
    except BaseException:
        if created:
            for artifact in reversed(artifacts):
                try:
                    if artifact.is_file() and not artifact.is_symlink():
                        artifact.unlink()
                except OSError:
                    pass
        raise

    recipes = runtime_profile_recipes(project, session, gates)
    terminal_states = [
        (terminal_command_receipt(project, session, gate["gate_id"]) or {}).get("runner_state", "")
        for gate in gates
    ]
    if not recipes:
        resume_state = "blocked_terminal_failure" if (
            any(gate.get("status") == "failed" for gate in gates)
            or "failed" in terminal_states
        ) else "complete"
    elif recipes[0]["gate_kind"] == "runtime_status":
        resume_state = "status_required"
    else:
        resume_state = "start_required"
    print(json.dumps({
        "contract_version": RUNTIME_PROFILE_VERSION,
        "state": "initialized" if created else "existing",
        "profile": RUNTIME_PROFILE,
        "profile_path": path.relative_to(project).as_posix(),
        "resume_state": resume_state,
        "run_recipes": recipes,
    }, ensure_ascii=False, sort_keys=True, separators=(",", ":")))
    return 0


def load_runtime_profile(project: Path, session: str) -> dict:
    path = runtime_profile_path(project, session)
    if path.is_symlink() or not path.is_file():
        raise GateError("Runtime Gate profile is not initialized")
    profile = json.loads(path.read_text(encoding="utf-8"))
    if (
        not isinstance(profile, dict)
        or profile.get("contract_version") != RUNTIME_PROFILE_VERSION
        or profile.get("profile") != RUNTIME_PROFILE
        or profile.get("project") != str(project)
        or profile.get("session_id") != session
        or profile.get("bindings") != ["source", "runtime", "runtime_cohort", "runtime_instance"]
        or not isinstance(profile.get("gate_ids"), dict)
        or set(profile["gate_ids"]) != RUNTIME_GATE_KINDS
        or not all(isinstance(value, str) and value for value in profile["gate_ids"].values())
    ):
        raise GateError("Runtime Gate profile contract or identity differs")
    current = current_runtime_profile_inputs(project, str(profile.get("address", "")))
    for key, value in current.items():
        if profile.get(key) != value:
            raise GateError(f"Runtime Gate profile current {key} identity differs")
    return profile


def command_run_runtime_profile(args, project: Path, session: str) -> int:
    profile = load_runtime_profile(project, session)
    state = sync_gates(project, session, load_state(project, session))
    if state.get("runtime_profile") != profile:
        raise GateError("Runtime Gate profile state identity differs")
    gates = {gate["kind"]: gate for gate in runtime_profile_gates(project, session, state)}
    gate = gates[args.gate_kind]
    if profile["gate_ids"].get(args.gate_kind) != gate["gate_id"]:
        raise GateError("Runtime Gate profile Gate identity differs")
    if args.gate_kind == "runtime_status":
        start = gates["runtime_start"]
        current = dict(identities(project), project=project)
        if effective_status(start, current) != "passed":
            raise GateError("Runtime status Gate requires the current runtime_start Gate to pass first")
    command = [profile["cli"], "runtime-process", "status", "--project", str(project)]
    if args.gate_kind == "runtime_start":
        command = [
            profile["cli"], "runtime-process", "start", "--project", str(project),
            "--bundle", profile["bundle"], "--address", profile["address"],
        ]
    namespace = argparse.Namespace(
        gate_id=gate["gate_id"], bind=list(profile["bindings"]), note="",
        cwd=".", expect_exit=0, expect_json_contract="", expect_json_state="",
        expect_json_diagnostic_code=[], command=command, profile_owned=True,
    )
    return command_run(namespace, project, session)


