def validate_command_for_gate(gate: dict, command: list[str], project: Path) -> str:
    label = gate["label"]
    kind = command_kind(gate, command, project)
    if kind != "generic":
        return kind
    lowered = " ".join(command).lower()
    label_value = f" {label.lower()} "
    if "module-focused" in label_value and "test" in label_value:
        executable = Path(command[0]).name.lower()
        if executable not in {"go", "go.exe"} or len(command) < 2 or command[1] != "test":
            raise GateError(f"command does not prove Gate '{label}'")
        return kind
    allowed: list[str] = []
    for category_token, category_commands in COMMAND_CATEGORIES:
        if category_token in label_value:
            allowed.extend(category_commands)
    if "focused tests" in label_value or " tests pass" in label_value or "full tests" in label_value:
        executable = Path(command[0]).name.lower()
        go_test = executable in {"go", "go.exe"} and (
            len(command) >= 2 and command[1] == "test"
        )
        javascript_test = (
            executable in {"npm", "npm.exe", "pnpm", "pnpm.exe", "yarn", "yarn.exe"}
            and len(command) >= 2
            and (
                command[1] == "test"
                or len(command) >= 3 and command[1:3] == ["run", "test"]
            )
        ) or executable in {"vitest", "vitest.exe", "jest", "jest.exe"}
        if not go_test and not javascript_test:
            raise GateError(f"command does not prove Gate '{label}'")
        return kind
    if allowed and not any(token in lowered for token in allowed):
        raise GateError(f"command does not prove Gate '{label}'")
    return kind


def validate_safe_argv(command: list[str]) -> None:
    for value in command:
        if SECRET_OPTION.match(value) or SECRET_URI.match(value) or SECRET_ASSIGNMENT.search(value):
            raise GateError("command argv contains a secret-bearing option or credential URI")
    executable = Path(command[0]).name.lower() if command else ""
    if executable not in {"bash", "bash.exe", "zsh", "zsh.exe", "sh", "sh.exe", "dash", "dash.exe"}:
        return
    script = ""
    for index, value in enumerate(command[:-1]):
        if value in {"-c", "-lc"}:
            script = command[index + 1]
            break
    if re.search(r"(?<!\|)\|(?!\|)", script) and not re.search(
        r"\bset\s+(?:-[A-Za-z]*o\s+pipefail|-o\s+pipefail)\b", script,
    ):
        raise GateError("shell pipelines require set -o pipefail (or set -euo pipefail)")


def command_cwd(project: Path, value: str) -> tuple[Path, str]:
    candidate = Path(value).expanduser()
    path = (candidate if candidate.is_absolute() else project / candidate).resolve(strict=True)
    if project != path and project not in path.parents:
        raise GateError("command cwd must remain inside the project")
    if path.is_symlink() or not path.is_dir():
        raise GateError("command cwd must be a real project directory")
    return path, path.relative_to(project).as_posix() if path != project else "."


def parse_expected_json(stdout: bytes) -> dict:
    if len(stdout) > MAX_EXPECTED_JSON_BYTES:
        raise GateError("expected JSON stdout exceeds the bounded validation limit")
    try:
        document = json.loads(stdout.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise GateError("command stdout is not one valid JSON document") from error
    if not isinstance(document, dict):
        raise GateError("command stdout JSON must be an object")
    return document


def bounded_diagnostic_string(value, field: str, maximum: int, *, required: bool = False) -> str | None:
    if value is None and not required:
        return None
    if not isinstance(value, str) or (required and not value) or len(value) > maximum:
        raise GateError(f"project check diagnostic {field} is invalid or exceeds its bound")
    if any(ord(character) < 32 and character != "\t" for character in value):
        raise GateError(f"project check diagnostic {field} contains control characters")
    return value


def sanitize_diagnostic_message(value: str) -> tuple[str, bool]:
    sanitized = SENSITIVE_DIAGNOSTIC_ASSIGNMENT.sub(lambda match: f"{match.group(1)}=<redacted>", value)
    sanitized = SENSITIVE_DIAGNOSTIC_URI.sub(lambda match: f"{match.group(1)}<redacted>@", sanitized)
    sanitized = SENSITIVE_DIAGNOSTIC_BEARER.sub("Bearer <redacted>", sanitized)
    return sanitized, sanitized != value


def bounded_failure_stderr(stderr: bytes) -> dict | None:
    if not stderr:
        return None
    retained = stderr[:MAX_FAILURE_STDERR_BYTES]
    summary = retained.decode("utf-8", errors="replace")
    summary = "".join(
        character if character in "\n\r\t" or ord(character) >= 32 else "�"
        for character in summary
    )
    summary, redacted = sanitize_diagnostic_message(summary)
    return {
        "summary": summary,
        "original_bytes": len(stderr),
        "retained_bytes": len(retained),
        "truncated": len(stderr) > len(retained),
        "redacted": redacted,
    }

