#!/usr/bin/env python3
import hashlib
import importlib.util
import json
import sys
import urllib.error
import urllib.request
import uuid
from pathlib import Path

BASE = "http://127.0.0.1:19111"
WORKSPACE = "default"
PROJECT = Path(__file__).resolve().parents[2]
CORE_PATH = Path("/Users/tiger/.codex/skills/domainry-builder-v1/assets/acceptance-harness-core.py")
CORE_SPEC = importlib.util.spec_from_file_location("domainry_acceptance_core", CORE_PATH)
CORE = importlib.util.module_from_spec(CORE_SPEC)
CORE_SPEC.loader.exec_module(CORE)
RUNTIME_STATE = json.loads((PROJECT / ".domainry/builder/runtime/runtime-process.json").read_text())
CORE_RUNTIME = CORE.Runtime(BASE)
CORE_SESSIONS = CORE.Sessions(
    CORE_RUNTIME,
    str(PROJECT),
    workspace_id=WORKSPACE,
    database_identity_sha256=RUNTIME_STATE["database_identity_sha256"],
)


def recursive_value(value, keys):
    if isinstance(value, dict):
        for key in keys:
            candidate = value.get(key)
            if isinstance(candidate, str) and candidate:
                return candidate
        for candidate in value.values():
            found = recursive_value(candidate, keys)
            if found:
                return found
    elif isinstance(value, list):
        for candidate in value:
            found = recursive_value(candidate, keys)
            if found:
                return found
    return ""


def recursive_items(value):
    if isinstance(value, dict):
        items = value.get("items")
        if isinstance(items, list):
            return items
        for candidate in value.values():
            found = recursive_items(candidate)
            if found is not None:
                return found
    return None


class Session:
    def __init__(self, actor):
        self.actor = actor
        self.session = CORE_SESSIONS.context(actor, "workforce")
        context = self.session["principal_context"]
        encoded = json.dumps(context, sort_keys=True, separators=(",", ":")).encode()
        self.context_sha256 = hashlib.sha256(encoded).hexdigest()

    def request(self, method, path, body=None, authenticated=True, idempotency_key=""):
        exchange = CORE_RUNTIME.request(
            method,
            path,
            session=self.session if authenticated else None,
            body=body,
            idempotency_key=idempotency_key,
        )
        payload = exchange.body if exchange.body is not None else exchange.body_list
        return exchange.status, payload or {}

    def records(self, object_key):
        status, payload = self.request("GET", f"/objects/{object_key}/records")
        if status != 200:
            raise RuntimeError(f"{self.actor}: list {object_key} returned {status}")
        return recursive_items(payload) or []

    def record(self, object_key, record_id):
        status, payload = self.request("GET", f"/objects/{object_key}/records/{record_id}")
        if status != 200:
            raise RuntimeError(f"{self.actor}: read {object_key} returned {status}")
        return payload

    def action(self, object_key, record_id, action_key, fields, request_id, expected_updated_at):
        headers = {
            "Accept": "application/json",
            "Content-Type": "application/json",
            "Authorization": "Bearer " + self.session["token"],
            "Idempotency-Key": request_id,
            "If-Match": '"' + expected_updated_at + '"',
            **self.session["request_headers"],
        }
        payload = json.dumps(
            {"data": {
                **fields,
                "request_id": request_id,
                "expected_updated_at": expected_updated_at,
            }},
            separators=(",", ":"),
        ).encode()
        request = urllib.request.Request(
            BASE + f"/objects/{object_key}/records/{record_id}/actions/{action_key}",
            data=payload,
            headers=headers,
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=15) as response:
                raw = response.read()
                return response.status, json.loads(raw) if raw else {}
        except urllib.error.HTTPError as error:
            raw = error.read()
            try:
                body = json.loads(raw) if raw else {}
            except json.JSONDecodeError:
                body = {}
            return error.code, body


def record_data(record):
    if not isinstance(record, dict):
        return {}
    data = record.get("data")
    return data if isinstance(data, dict) else record


def record_id(record):
    return recursive_value(record, ("id", "record_id"))


def find_record(records, field, expected):
    for record in records:
        if record_data(record).get(field) == expected:
            return record
    raise RuntimeError(f"target record missing: {field}")


def main():
    north = Session("north_sales")
    east = Session("east_sales")
    director = Session("sales_director")

    lead = find_record(north.records("lead"), "company_name", "华北高额合格线索")
    lead_id = record_id(lead)
    if not lead_id or record_data(lead).get("status") != "qualified":
        raise RuntimeError("canary lead is not a qualified exact target")

    request_id = "canary-j04-request-" + uuid.uuid4().hex
    status, requested = north.action(
        "lead", lead_id, "lead.request_lead_conversion", {}, request_id, lead.get("updated_at", "")
    )
    if status != 200:
        code = recursive_value(requested, ("code", "error_code"))
        raise RuntimeError(f"request conversion returned {status} code={code or 'missing'}")
    approval_id = recursive_value(requested, ("approval_id", "ApprovalID"))
    if not approval_id:
        approval = find_record(director.records("conversion_approval"), "lead_id", lead_id)
        approval_id = record_id(approval)
    pending = director.record("conversion_approval", approval_id)
    if record_data(pending).get("status") != "pending":
        raise RuntimeError("conversion request did not create a pending approval")
    pending_sha = hashlib.sha256(
        json.dumps(pending, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()

    denied_id = "canary-j04-denied-" + uuid.uuid4().hex
    denied_status, denied_payload = east.action(
        "conversion_approval",
        approval_id,
        "conversion_approval.resolve_conversion_approval",
        {"resolution": "approved", "comment": "unauthorized canary contrast"},
        denied_id,
        pending.get("updated_at", ""),
    )
    denied_code = recursive_value(denied_payload, ("code", "error_code"))
    if denied_status not in (403, 404) or not denied_code:
        raise RuntimeError(f"non-director contrast returned {denied_status} without typed rejection")
    pending_after_denial = director.record("conversion_approval", approval_id)
    denied_sha = hashlib.sha256(
        json.dumps(pending_after_denial, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    if denied_sha != pending_sha:
        raise RuntimeError("denied approval attempt changed durable state")

    decision_id = "canary-j04-approve-" + uuid.uuid4().hex
    approved_status, approved_result = director.action(
        "conversion_approval",
        approval_id,
        "conversion_approval.resolve_conversion_approval",
        {"resolution": "approved", "comment": "J04 semantic canary approval"},
        decision_id,
        pending_after_denial.get("updated_at", ""),
    )
    if approved_status != 200 or not recursive_value(approved_result, ("customer_id", "CustomerID")):
        raise RuntimeError(f"director approval returned {approved_status} without customer identity")

    approval_after = director.record("conversion_approval", approval_id)
    lead_after = north.record("lead", lead_id)
    customers = north.records("customer")
    matching_customers = [
        row for row in customers if record_data(row).get("source_lead_id") == lead_id
    ]
    notification_status, notifications = north.request("GET", "/business/notifications")
    notification_items = recursive_items(notifications) or []
    notification_match = any(
        "conversion" in json.dumps(item, ensure_ascii=False).lower()
        or "转化" in json.dumps(item, ensure_ascii=False)
        for item in notification_items
    )
    if record_data(approval_after).get("status") != "approved":
        raise RuntimeError("approval state was not persisted")
    if record_data(lead_after).get("status") != "converted":
        raise RuntimeError("lead conversion was not visible to the requester")
    if len(matching_customers) != 1:
        raise RuntimeError("atomic conversion did not yield exactly one linked customer")
    if notification_status != 200 or not notification_match:
        raise RuntimeError("requester approval notification was not visible")

    print(json.dumps({
        "contract_version": "domainry-semantic-canary-result-v1",
        "state": "passed",
        "journey": "J04",
        "runtime": BASE,
        "principal_contexts": {
            "north_sales": north.context_sha256,
            "east_sales": east.context_sha256,
            "sales_director": director.context_sha256,
        },
        "facts": {
            "exact_lead_id_non_empty": bool(lead_id),
            "exact_approval_id_non_empty": bool(approval_id),
            "denied_status": denied_status,
            "denied_error_code_non_empty": bool(denied_code),
            "denied_state_unchanged": True,
            "approval_status": "approved",
            "lead_status": "converted",
            "linked_customer_count": 1,
            "requester_notification_visible": True,
        },
    }, sort_keys=True, separators=(",", ":")))


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print(json.dumps({
            "contract_version": "domainry-semantic-canary-result-v1",
            "state": "failed",
            "reason": str(error),
        }, sort_keys=True, separators=(",", ":")))
        sys.exit(1)

