		if strings.TrimSpace(commit.Operation) != operation || strings.TrimSpace(commit.Object.Key) != objectKey {
			continue
		}
		candidateID := strings.TrimSpace(commit.Record.ID)
		if candidateID == "" {
			candidateID = strings.TrimSpace(commit.RecordID)
		}
