	if value.AlertState == notificationmodel.NotificationAlertFiring && occurrences == 0 {
		occurrences = 1
	}
	return []any{value.ID, value.WorkspaceID, value.RecipientUserID, value.Surface, value.EventID, value.EventType, value.Source, value.Category, value.Severity,
		value.Title, value.Body, notificationInboxSearchText(value), raw, value.SubjectType, value.SubjectID, value.ActionState, value.AlertState, value.GroupKey,
		occurrences, value.FirstOccurredAt, value.LastOccurredAt, value.ReadAt, value.ArchivedAt, value.ExpiresAt, value.CreatedAt, value.UpdatedAt}
}

func (r NotificationStore) notificationInboxItemUpsertClause() string {
