		assignments := []string{occurrences + " = IF(" + condition + ", " + occurrences + " + IF(VALUES(" + r.store.Identifier("alert_state") + ") = 'resolved', 0, 1), " + occurrences + ")"}
		for _, column := range mutable {
			identifier := r.store.Identifier(column)
			assignments = append(assignments, identifier+" = IF("+condition+", VALUES("+identifier+"), "+identifier+")")
		}
		assignments = append(assignments, last+" = IF("+condition+", VALUES("+last+"), "+last+")")
