	}
	assignments := []string{occurrences + " = " + r.store.TableIdentifier("notification_inbox_items") + "." + occurrences + " + CASE WHEN excluded." + r.store.Identifier("alert_state") + " = 'resolved' THEN 0 ELSE 1 END"}
	for _, column := range mutable {
		identifier := r.store.Identifier(column)
		assignments = append(assignments, identifier+" = excluded."+identifier)
	}
	assignments = append(assignments, last+" = excluded."+last)
	return " ON CONFLICT (" + r.store.Identifier("workspace_id") + ", " + r.store.Identifier("id") + ") DO UPDATE SET " + strings.Join(assignments, ", ") + " WHERE " + r.store.TableIdentifier("notification_inbox_items") + "." + last + " <= excluded." + last
}

