func (s *NotificationInboxDomainService) PrepareIntent(intent notificationmodel.NotificationIntent) (notificationmodel.NotificationEvent, error) {
	event, err := s.CompileIntent(intent)
	if err != nil {
		return notificationmodel.NotificationEvent{}, err
	}
	event, err = notificationvalidation.NotificationValidateInboxEvent(event)
	if err != nil {
		return notificationmodel.NotificationEvent{}, err
	}
	if err := s.validateEventActions(event); err != nil {
		return notificationmodel.NotificationEvent{}, err
	}
	now := notificationmodel.NotificationTimestamp(s.clock.Now())
	event.CreatedAt, event.UpdatedAt = now, now
	for index := range event.ChannelPlans {
		plan := &event.ChannelPlans[index]
		plan.ID = notificationInboxStableID(event.WorkspaceID, event.ID, plan.Channel, plan.ConnectorKey, plan.Operation, fmt.Sprint(plan.EscalationStep))
		plan.WorkspaceID, plan.EventID, plan.Status = event.WorkspaceID, event.ID, "queued"
		plan.CreatedAt, plan.UpdatedAt = now, now
	}
	return event, nil
}

