func (s *NotificationInboxDomainService) validateIntentAudienceResolvers(eventType notificationmodel.NotificationEventType, requested []string) ([]string, error) {
	requested = notificationUniqueResolvedRecipients(requested)
	if len(requested) == 0 {
		return nil, nil
	}
	allowed := map[string]bool{}
	for _, key := range eventType.AudienceResolvers {
		allowed[strings.TrimSpace(key)] = true
	}
	if s.rules != nil {
		if rule, found := s.rules.ResolveNotificationRule(eventType.Key); found {
			for _, key := range rule.AudienceResolvers {
				allowed[strings.TrimSpace(key)] = true
			}
		}
	}
	for _, key := range requested {
		if !allowed[key] {
			return nil, notificationBadRequest("backend.notification.inbox_audience_resolver_not_allowed", "resolver_key", key)
		}
	}
	return requested, nil
}

func notificationCompileInboxSnapshot(eventType notificationmodel.NotificationEventType, locale string, content notificationmodel.NotificationInboxEventTypeContent, variables map[string]any, subjectID string) (notificationmodel.NotificationInboxSnapshot, error) {
	title, err := notificationvalidation.NotificationRenderRestricted(content.Title, variables, false)
	if err != nil {
		return notificationmodel.NotificationInboxSnapshot{}, notificationBadRequest("backend.notification.inbox_template_render_failed", "field", "title")
	}
	body, err := notificationvalidation.NotificationRenderRestricted(content.Body, variables, false)
	if err != nil {
		return notificationmodel.NotificationInboxSnapshot{}, notificationBadRequest("backend.notification.inbox_template_render_failed", "field", "body")
	}
	facts := make([]notificationmodel.NotificationTemplateFact, 0, len(content.Facts))
	for _, fact := range content.Facts {
		key, keyErr := notificationvalidation.NotificationRenderRestricted(fact.Key, variables, false)
		value, valueErr := notificationvalidation.NotificationRenderRestricted(fact.Value, variables, false)
		if keyErr != nil || valueErr != nil {
			return notificationmodel.NotificationInboxSnapshot{}, notificationBadRequest("backend.notification.inbox_template_render_failed", "field", "facts")
		}
		if strings.TrimSpace(value) == "" {
			continue
		}
		facts = append(facts, notificationmodel.NotificationTemplateFact{Key: key, Value: value})
	}
	actions := make([]notificationmodel.NotificationInboxActionRef, 0, len(eventType.Actions))
	for _, descriptor := range eventType.Actions {
		label, labelErr := notificationvalidation.NotificationRenderRestricted(content.ActionLabels[descriptor.Key], variables, false)
		if labelErr != nil || strings.TrimSpace(label) == "" {
			return notificationmodel.NotificationInboxSnapshot{}, notificationBadRequest("backend.notification.inbox_template_render_failed", "field", "action_label", "action_key", descriptor.Key)
		}
		actions = append(actions, notificationmodel.NotificationInboxActionRef{Key: descriptor.Key, Kind: descriptor.Kind, Label: label, ResourceType: descriptor.ResourceType, ResourceID: strings.TrimSpace(subjectID), Style: "primary"})
	}
	snapshot := notificationmodel.NotificationInboxSnapshot{Title: title, Body: body, Facts: facts, Actions: actions, TemplateKey: eventType.TemplateKey, TemplateVersion: eventType.Version, TemplateLocale: locale}
	snapshot.TemplateContentHash = notificationInboxSnapshotHash(snapshot)
	return snapshot, nil
}

func (s *NotificationInboxDomainService) compileChannelPlans(eventTypeKey string, intent notificationmodel.NotificationIntent, snapshot notificationmodel.NotificationInboxSnapshot) []notificationmodel.NotificationChannelPlan {
	if s.rules == nil {
		return nil
	}
	rule, found := s.rules.ResolveNotificationRule(eventTypeKey)
	if !found || !rule.Enabled {
		return nil
	}
	plans := []notificationmodel.NotificationChannelPlan{}
	for _, channel := range rule.Channels {
		if strings.TrimSpace(channel.Channel) == "in_app" {
			continue
		}
		deliveryMode := strings.TrimSpace(channel.DeliveryMode)
		if deliveryMode == "" {
			deliveryMode = "immediate"
		}
		nextAttemptAt := notificationChannelFirstAttemptAt(intent.OccurredAt, channel.DelaySeconds, channel.DigestWindowSeconds)
		plans = append(plans, notificationmodel.NotificationChannelPlan{
			Channel: strings.TrimSpace(channel.Channel), TemplateKey: strings.TrimSpace(channel.TemplateKey), ConnectorKey: strings.TrimSpace(channel.ConnectorKey),
			ConnectionKey: strings.TrimSpace(channel.ConnectionKey), Operation: strings.TrimSpace(channel.Operation), RecipientUserIDs: append([]string(nil), intent.RecipientUserIDs...),
			Locale: strings.TrimSpace(intent.Locale), Variables: cloneNotificationVariables(intent.Variables), DedupeKey: strings.TrimSpace(intent.DedupeKey), Mandatory: channel.Mandatory,
			DeliveryMode: deliveryMode, DigestKey: notificationChannelDigestKey(intent, channel), DigestMaximumItems: channel.DigestMaximumItems,
			DigestItemTitle: snapshot.Title, DigestItemBody: snapshot.Body,
			EscalationStep: channel.EscalationStep, CancelWhenActionTerminal: channel.CancelWhenActionTerminal, NextAttemptAt: nextAttemptAt,
		})
	}
	return plans
}

func notificationChannelFirstAttemptAt(occurredAt string, delaySeconds, digestWindowSeconds int) string {
	value, err := time.Parse(time.RFC3339Nano, strings.TrimSpace(occurredAt))
	if err != nil {
		return ""
	}
	delay := delaySeconds
	if digestWindowSeconds > 0 {
		delay = digestWindowSeconds
	}
	if delay <= 0 {
		return ""
	}
	return notificationmodel.NotificationTimestamp(value.Add(time.Duration(delay) * time.Second))
}

func notificationChannelDigestKey(intent notificationmodel.NotificationIntent, channel notificationmodel.NotificationRuleChannel) string {
	if strings.TrimSpace(channel.DeliveryMode) != "digest" {
		return ""
	}
	return notificationInboxStableID(intent.WorkspaceID, intent.EventType, channel.Channel, channel.TemplateKey, channel.ConnectionKey, strings.Join(intent.RecipientUserIDs, ","), strings.TrimSpace(intent.Locale))
}

func cloneNotificationVariables(source map[string]any) map[string]any {
	if source == nil {
		return nil
	}
	result := make(map[string]any, len(source))
	for key, value := range source {
		result[key] = value
	}
	return result
}

