// PublishEvent durably records the source intent. Materialization is owned by
// the background worker so producer latency never includes audience resolution
// or per-recipient projection work.
func (s *NotificationInboxDomainService) PublishEvent(ctx context.Context, value notificationmodel.NotificationEvent) (notificationmodel.NotificationEvent, bool, error) {
	nowTime := s.clock.Now().UTC()
	now := notificationmodel.NotificationTimestamp(nowTime)
	validated, err := notificationvalidation.NotificationValidateInboxEvent(value)
	if err != nil {
		return notificationmodel.NotificationEvent{}, false, err
	}
	if err := s.validateEventActions(validated); err != nil {
		return notificationmodel.NotificationEvent{}, false, err
	}
	validated.CreatedAt, validated.UpdatedAt = now, now
	return s.repository.EnqueueInboxEvent(ctx, validated)
}

func (s *NotificationInboxDomainService) ProcessDueEvents(ctx context.Context, limit int) (int, error) {
	if limit <= 0 || limit > 100 {
		limit = 25
	}
	now := s.clock.Now().UTC()
	values, err := s.repository.ListDueInboxEvents(ctx, notificationmodel.NotificationTimestamp(now), limit)
	if err != nil {
		return 0, err
	}
	processed := 0
	for _, value := range values {
		completed, processErr := s.processEventAt(ctx, value.WorkspaceID, value.ID, now)
		if processErr != nil {
			return processed, processErr
		}
		if completed {
			processed++
		}
	}
	return processed, nil
}

func (s *NotificationInboxDomainService) ProcessEvent(ctx context.Context, workspaceID, id string) (bool, error) {
	return s.processEventAt(ctx, strings.TrimSpace(workspaceID), strings.TrimSpace(id), s.clock.Now().UTC())
}

func (s *NotificationInboxDomainService) processEventAt(ctx context.Context, workspaceID, id string, now time.Time) (bool, error) {
	eventCtx := requestcontext.WithWorkspaceID(ctx, workspaceID)
	claimed, ok, err := s.repository.ClaimInboxEvent(eventCtx, workspaceID, id, s.workerID, notificationmodel.NotificationTimestamp(now), notificationmodel.NotificationTimestamp(now.Add(notificationInboxLeaseDuration)))
	if err != nil || !ok {
		return false, err
	}
	if materializeErr := s.materializeClaimedEvent(eventCtx, claimed); materializeErr != nil {
		if retryErr := s.recordInboxEventFailure(eventCtx, claimed, materializeErr, now); retryErr != nil {
			return false, retryErr
		}
		return false, nil
	}
	return true, nil
}

func (s *NotificationInboxDomainService) recordInboxEventFailure(ctx context.Context, event notificationmodel.NotificationEvent, cause error, now time.Time) error {
	updatedAt := notificationmodel.NotificationTimestamp(now)
	stage, errorCode := "materialization", "backend.notification.inbox_materialization_failed"
	if code := apperror.CodeOf(cause); strings.HasPrefix(code, "backend.notification.inbox_audience_") {
		stage, errorCode = "audience_resolution", code
	}
	if event.AttemptCount+1 >= notificationInboxMaximumAttempts {
		return s.repository.FailInboxEvent(ctx, event, stage, errorCode, updatedAt)
	}
	next := notificationmodel.NotificationTimestamp(now.Add(notificationInboxRetryDelay(event.AttemptCount + 1)))
	return s.repository.RetryInboxEvent(ctx, event, stage, errorCode, next, updatedAt)
}

func notificationInboxRetryDelay(attempt int) time.Duration {
	if attempt < 1 {
		attempt = 1
	}
	if attempt > 6 {
		attempt = 6
	}
	return time.Duration(1<<(attempt-1)) * time.Minute
}

func (s *NotificationInboxDomainService) materializeClaimedEvent(ctx context.Context, event notificationmodel.NotificationEvent) error {
	recipients := append([]string(nil), event.RecipientUserIDs...)
	for _, resolverKey := range event.AudienceResolverKeys {
		if s.audienceResolver == nil {
			return &apperror.AppError{Kind: apperror.KindUnavailable, Code: "backend.notification.inbox_audience_resolver_unavailable"}
		}
		resolved, err := s.audienceResolver(ctx, resolverKey, event)
		if err != nil {
			return &apperror.AppError{Kind: apperror.KindUnavailable, Code: "backend.notification.inbox_audience_resolution_failed", Err: err}
		}
		recipients = append(recipients, resolved...)
	}
	recipients = notificationUniqueResolvedRecipients(recipients)
	if len(recipients) == 0 || len(recipients) > 500 {
		return &apperror.AppError{Kind: apperror.KindUnavailable, Code: "backend.notification.inbox_audience_resolution_empty"}
	}
	event.RecipientUserIDs = recipients
	for index := range event.ChannelPlans {
		event.ChannelPlans[index].RecipientUserIDs = append([]string(nil), recipients...)
	}
	items := make([]notificationmodel.NotificationInboxItem, 0, len(event.RecipientUserIDs))
	for _, recipient := range event.RecipientUserIDs {
		locale := ""
		if s.recipientLocale != nil {
			var err error
			locale, err = s.recipientLocale(ctx, event.WorkspaceID, recipient)
			if err != nil {
				return err
			}
		}
		items = append(items, notificationInboxItemFromEvent(event, recipient, locale))
	}
	return s.repository.MaterializeInboxEvent(ctx, event, items)
}

func notificationUniqueResolvedRecipients(values []string) []string {
	seen, result := map[string]bool{}, make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" || seen[value] {
			continue
		}
		seen[value] = true
		result = append(result, value)
	}
	return result
}
