func (r NotificationStore) EnqueueInboxEvent(ctx context.Context, value notificationmodel.NotificationEvent) (notificationmodel.NotificationEvent, bool, error) {
	workspaceID, err := requireNotificationWorkspaceID(value.WorkspaceID)
	if err != nil {
		return notificationmodel.NotificationEvent{}, false, err
	}
	value.WorkspaceID = workspaceID
	if err := r.registerInboxWorkerQueueScope(ctx, r.database(), value.WorkspaceID, value.UpdatedAt); err != nil {
		return notificationmodel.NotificationEvent{}, false, err
	}
	ctx = notificationWorkspaceContext(ctx, value.WorkspaceID)
	raw, err := json.Marshal(value)
	if err != nil {
		return notificationmodel.NotificationEvent{}, false, fmt.Errorf("encode notification event: %w", err)
	}
	columns := notificationInboxEventColumns()
	query := r.store.InsertStatement("notification_events", columns)
	_, err = r.database().ExecContext(ctx, query, notificationInboxEventValues(value, string(raw))...)
	if err == nil {
		r.PublishCommittedInboxEventWakeup(ctx, value)
		return value, true, nil
	}
	existing, found, readErr := r.getInboxEventBySource(ctx, workspaceID, value.Source, value.SourceEventID)
	if readErr != nil {
		return notificationmodel.NotificationEvent{}, false, fmt.Errorf("enqueue notification event: %w", err)
	}
	if found {
		return existing, false, nil
	}
	return notificationmodel.NotificationEvent{}, false, fmt.Errorf("enqueue notification event: %w", err)
}

// InsertInboxEventTx participates in a producer-owned database transaction.
// The caller must pass an already compiled and validated event; ownership of
// event schema and columns remains in this adapter.
type NotificationTransactionExecutor interface {
	ExecContext(context.Context, string, ...any) (sql.Result, error)
}

func (r NotificationStore) InsertInboxEventTx(ctx context.Context, tx NotificationTransactionExecutor, value notificationmodel.NotificationEvent) error {
	if err := r.registerInboxWorkerQueueScope(ctx, tx, value.WorkspaceID, value.UpdatedAt); err != nil {
		return err
	}
	ctx = notificationWorkspaceContext(ctx, value.WorkspaceID)
	raw, err := json.Marshal(value)
	if err != nil {
		return fmt.Errorf("encode notification event: %w", err)
	}
	_, err = tx.ExecContext(ctx, r.store.InsertStatement("notification_events", notificationInboxEventColumns()), notificationInboxEventValues(value, string(raw))...)
	if err != nil {
		return databasefailure.ConstraintError(fmt.Errorf("insert notification event intent: %w", err), "notification_event", value.Source+"/"+value.SourceEventID, mutation.MutationConflictUnique)
	}
	if transactioncontract.ActiveTransaction(ctx) {
		if err := r.registerInboxEventAfterCommit(ctx, value); err != nil {
			return err
		}
	}
	return nil
}

func (r NotificationStore) registerInboxEventAfterCommit(ctx context.Context, event notificationmodel.NotificationEvent) error {
	return transactioncontract.RegisterAfterCommit(ctx, transactioncontract.AfterCommitHook{
		Name: "wake notification inbox " + event.ID, Purpose: transactioncontract.AfterCommitDurableWorkWakeup, DurableRecovery: true,
		Run: func(hookCtx context.Context) error { r.PublishCommittedInboxEventWakeup(hookCtx, event); return nil },
	})
}

func (r NotificationStore) PublishCommittedInboxEventWakeup(_ context.Context, event notificationmodel.NotificationEvent) {
	workspace, err := identitymodel.NewWorkspaceID(event.WorkspaceID)
	if r.store == nil || err != nil || strings.TrimSpace(event.ID) == "" {
		return
	}
	r.store.WorkerWakeups().Publish(workerplatform.DurableTaskLocator{QueueKind: "notification_inbox", WorkspaceID: workspace.String(), TaskID: strings.TrimSpace(event.ID)})
}

func notificationInboxEventValues(value notificationmodel.NotificationEvent, raw string) []any {
	return []any{
		value.ID, value.WorkspaceID, value.Source, value.SourceEventID, value.Status, raw, value.AttemptCount,
		value.NextAttemptAt, value.LastErrorCode, value.LeaseOwner, value.LeaseExpiresAt, value.FencingToken,
		value.OccurredAt, value.CreatedAt, value.UpdatedAt,
	}
}

func (r NotificationStore) ListDueInboxEvents(ctx context.Context, now string, limit int) ([]notificationmodel.NotificationEvent, error) {
	if limit <= 0 {
		limit = 25
	}
	workspaces, err := r.store.WorkerQueueScopePage(ctx, r.database(), "notification_inbox", notificationWorkspaceScanLimit(limit))
	if err != nil {
		return nil, err
	}
	values := []notificationmodel.NotificationEvent{}
	for _, workspaceID := range workspaces {
		workspaceValues, listErr := r.listDueInboxEventsForWorkspace(notificationWorkspaceContext(ctx, workspaceID), workspaceID, now, limit)
		if listErr != nil {
			return nil, listErr
		}
		values = append(values, workspaceValues...)
	}
	sort.SliceStable(values, func(i, j int) bool {
		if values[i].OccurredAt == values[j].OccurredAt {
			return values[i].ID < values[j].ID
		}
		return values[i].OccurredAt < values[j].OccurredAt
	})
	if len(values) > limit {
		values = values[:limit]
	}
	return values, nil
}

func notificationWorkspaceScanLimit(eventLimit int) int {
	return min(256, max(32, eventLimit*2))
}

func (r NotificationStore) listDueInboxEventsForWorkspace(ctx context.Context, workspaceID, now string, limit int) ([]notificationmodel.NotificationEvent, error) {
	columns := strings.Join(database.QuotedColumns(r.store, notificationInboxEventColumns()), ", ")
	query := "SELECT " + columns + " FROM " + r.store.TableIdentifier("notification_events") +
		" WHERE " + r.store.Identifier("workspace_id") + " = " + r.store.Placeholder(1) + " AND ((" + r.store.Identifier("status") + " = 'queued' AND (" + r.store.Identifier("next_attempt_at") + " = '' OR " + r.store.Identifier("next_attempt_at") + " <= " + r.store.Placeholder(2) + "))" +
		" OR (" + r.store.Identifier("status") + " = 'processing' AND " + r.store.Identifier("lease_expires_at") + " <= " + r.store.Placeholder(3) + "))" +
		" ORDER BY " + r.store.Identifier("occurred_at") + " ASC LIMIT " + fmt.Sprint(limit)
	rows, err := r.database().QueryContext(ctx, query, workspaceID, now, now)
	if err != nil {
		return nil, fmt.Errorf("list due notification events: %w", err)
	}
	defer rows.Close()
	values := []notificationmodel.NotificationEvent{}
	for rows.Next() {
		value, scanErr := scanInboxEvent(rows)
		if scanErr != nil {
			return nil, scanErr
		}
		values = append(values, value)
	}
	return values, rows.Err()
}

func (r NotificationStore) ClaimInboxEvent(ctx context.Context, workspaceID, id, owner, now, expiresAt string) (notificationmodel.NotificationEvent, bool, error) {
	workspaceID, id, owner = strings.TrimSpace(workspaceID), strings.TrimSpace(id), strings.TrimSpace(owner)
	if len(workspaceID) == 0 || len(id) == 0 || len(owner) == 0 || len(strings.TrimSpace(now)) == 0 || len(strings.TrimSpace(expiresAt)) == 0 {
		return notificationmodel.NotificationEvent{}, false, fmt.Errorf("notification event claim identity and lease are required")
	}
	ctx = notificationWorkspaceContext(ctx, workspaceID)
	query := "UPDATE " + r.store.TableIdentifier("notification_events") + " SET " +
		r.store.Identifier("status") + " = 'processing', " + r.store.Identifier("lease_owner") + " = " + r.store.Placeholder(1) + ", " +
		r.store.Identifier("lease_expires_at") + " = " + r.store.Placeholder(2) + ", " + r.store.Identifier("fencing_token") + " = " + r.store.Identifier("fencing_token") + " + 1, " +
		r.store.Identifier("updated_at") + " = " + r.store.Placeholder(3) + " WHERE " + r.store.Identifier("workspace_id") + " = " + r.store.Placeholder(4) +
		" AND " + r.store.Identifier("id") + " = " + r.store.Placeholder(5) +
		" AND ((" + r.store.Identifier("status") + " = 'queued' AND (" + r.store.Identifier("next_attempt_at") + " = '' OR " + r.store.Identifier("next_attempt_at") + " <= " + r.store.Placeholder(6) + "))" +
		" OR (" + r.store.Identifier("status") + " = 'processing' AND " + r.store.Identifier("lease_expires_at") + " <= " + r.store.Placeholder(7) + "))"
	result, err := r.database().ExecContext(ctx, query, owner, expiresAt, now, workspaceID, id, now, now)
	if err != nil {
		return notificationmodel.NotificationEvent{}, false, fmt.Errorf("claim notification event: %w", err)
	}
	count, err := result.RowsAffected()
	if err != nil || count != 1 {
		return notificationmodel.NotificationEvent{}, false, err
	}
	return r.getInboxEventByID(ctx, workspaceID, id)
}

func (r NotificationStore) MaterializeInboxEvent(ctx context.Context, event notificationmodel.NotificationEvent, items []notificationmodel.NotificationInboxItem) error {
	ctx = notificationWorkspaceContext(ctx, event.WorkspaceID)
	tx, err := r.database().BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if err := r.transitionAlertGroupsTx(ctx, tx, event, items); err != nil {
		return err
	}
	if err := r.upsertInboxItemsTx(ctx, tx, items); err != nil {
		return err
	}
	if len(event.ChannelPlans) > 0 {
		if err := r.registerNotificationWorkerQueueScope(ctx, tx, "notification_channel", event.WorkspaceID, event.UpdatedAt); err != nil {
			return err
		}
	}
	if err := r.insertNotificationChannelPlansTx(ctx, tx, event.ChannelPlans); err != nil {
		return err
	}
	now := event.UpdatedAt
	query := "UPDATE " + r.store.TableIdentifier("notification_events") + " SET " + r.store.Identifier("status") + " = 'materialized', " +
		r.store.Identifier("lease_owner") + " = '', " + r.store.Identifier("lease_expires_at") + " = '', " + r.store.Identifier("last_error_code") + " = '', " +
		r.store.Identifier("updated_at") + " = " + r.store.Placeholder(1) + " WHERE " + r.store.Identifier("workspace_id") + " = " + r.store.Placeholder(2) +
		" AND " + r.store.Identifier("id") + " = " + r.store.Placeholder(3) + " AND " + r.store.Identifier("status") + " = 'processing' AND " +
		r.store.Identifier("lease_owner") + " = " + r.store.Placeholder(4) + " AND " + r.store.Identifier("fencing_token") + " = " + r.store.Placeholder(5)
	result, err := tx.ExecContext(ctx, query, now, event.WorkspaceID, event.ID, event.LeaseOwner, event.FencingToken)
	if err != nil {
		return fmt.Errorf("finish notification event: %w", err)
	}
	count, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if count != 1 {
		return mutation.MutationConflict("notification_event", event.ID, mutation.MutationConflictLeaseLost, nil)
	}
	if err := tx.Commit(); err != nil {
		return err
	}
	for _, plan := range event.ChannelPlans {
		r.publishCommittedChannelPlanWakeup(plan)
	}
	return nil
}

