func (x *execution) harvestNotificationCase(plant *plantedCase, restart observationInput, lease string, workerPID int) {
	caseID := plant.acceptanceCase.ID
	// Exactly-once materialization: one committed event, one inbox item.
	items, err := x.inboxItemsForEvent(plant.eventID)
	if err != nil {
		x.skip(caseID, "database_capture_failed: "+err.Error())
		return
	}
	if len(items) > 1 {
		x.fail(caseID, fmt.Sprintf("the restarted worker materialized %d inbox items for one committed event: exactly-once recovery violated", len(items)))
		return
	}
	if len(items) == 0 {
		x.skip(caseID, "inbox_item_missing: the materialized event "+plant.eventID+" exposes no inbox item to refetch durably")
		return
	}
	item := items[0]
	itemID := textOf(item["id"])
	recipient := textOf(item["recipient_user_id"])
	if recipient == "" {
		recipient = textOf(item["user_id"])
	}
	if recipient == "" {
		x.skip(caseID, "inbox_recipient_unknown: the inbox item "+itemID+" names no recipient identity for the durable refetch")
		return
	}
	recipientSession, err := x.userSession(recipient)
	if err != nil {
		x.skip(caseID, err.Error())
		return
	}
	refetch, err := x.env.Runtime.Do(Request{Method: http.MethodGet, Path: notificationInboxPath + "/" + itemID, Session: recipientSession})
	if err != nil {
		x.skip(caseID, "runtime_unreachable: "+err.Error())
		return
	}
	if refetch.Status/100 != 2 {
		x.fail(caseID, fmt.Sprintf("the durable refetch after restart rejected the recipient: HTTP %d %s", refetch.Status, refetch.ErrorCode))
		return
	}
	count, err := x.env.Database.ActionExecutionCount(plant.key)
	if err != nil {
		x.skip(caseID, "database_capture_failed: "+err.Error())
		return
	}
	if count != 1 {
		x.fail(caseID, fmt.Sprintf("the staged idempotency key executed %d times across the restart", count))
		return
	}
	audit, err := x.env.Database.AuditByInvocation(plant.key)
	if err != nil {
		x.skip(caseID, "database_capture_failed: "+err.Error())
		return
	}
	if audit == nil {
		x.skip(caseID, "audit_event_not_found: no audit event correlates staged invocation "+plant.key)
		return
	}
	if reason := x.auditRedactionFailure(audit); reason != "" {
		x.fail(caseID, reason)
		return
	}
	httpFacts, err := httpExchangeFacts(plant.acceptanceCase, plant.operation, plant.path, plant.result, plant.session, plant.key, executionID(plant.execution))
	if err != nil {
		x.skip(caseID, err.Error())
		return
	}
	executionRow := normalizeRow(plant.execution)
	receipt := backendacceptance.IdempotencyReceiptFacts{
		KeySHA256: digestBytes([]byte(plant.key)), FingerprintSHA256: textOf(executionRow["request_fingerprint"]),
		Decision: "accepted", ExecutionCount: 1, OriginalReceiptID: executionID(plant.execution),
	}
	durableState := "unread"
	if textOf(objectOf(refetch.Body)["read_at"]) != "" || textOf(item["read_at"]) != "" {
		durableState = "read"
	}
	auditFacts := backendacceptance.AuditCorrelationFacts{
		RequestID: plant.result.RequestID, InvocationID: plant.key,
		AuditID: textOf(normalizeRow(audit)["id"]), TerminalState: "succeeded", SecretsRedacted: true,
		OutboxID: plant.eventID, NotificationID: itemID,
	}
	worker := backendacceptance.WorkerTerminalFacts{
		JobID: plant.eventID, State: "succeeded", Attempts: rowAttempts(plant.terminalRow, 1),
		LeaseToken: lease, WorkerPID: workerPID, Resumed: true, DuplicateEffects: 0,
	}
	refetchFacts := backendacceptance.DurableRefetchFacts{
		Method: http.MethodGet, Path: notificationInboxPath + "/" + itemID, Status: refetch.Status,
		EntityID: itemID, DurableState: durableState, AfterEventID: plant.eventID,
	}
	x.recordOrSkip(plant.acceptanceCase, []observationInput{
		{Kind: "http_exchange", CapturedFrom: "runtime_http", Facts: httpFacts},
		{Kind: "idempotency_receipt", CapturedFrom: "runtime_database", Facts: receipt},
		persistenceObservation(plant.subject, plant.session.WorkspaceID, plant.before, plant.after, nil),
		restart,
		{Kind: "worker_terminal", CapturedFrom: "runtime_worker", Facts: worker},
		{Kind: "durable_refetch", CapturedFrom: "runtime_http", Facts: refetchFacts},
		{Kind: "audit_correlation", CapturedFrom: "runtime_database", Facts: auditFacts},
	})
}

