// awaitRestartTerminal waits until every planted case reaches a terminal
// verdict (recovered, failed terminally, or deadline).
func (x *execution) awaitRestartTerminal(plants []*plantedCase) {
	for attempt := 0; attempt < restartTerminalAttempts; attempt++ {
		done := true
		for _, plant := range plants {
			if plant.terminalRow != nil || plant.terminalFailure != "" {
				continue
			}
			if err := x.checkRestartTerminal(plant); err != nil {
				plant.terminalFailure = "database_capture_failed: " + err.Error()
				continue
			}
			if plant.terminalRow == nil && plant.terminalFailure == "" {
				done = false
			}
		}
		if done {
			return
		}
		x.env.sleep(500 * time.Millisecond)
	}
	for _, plant := range plants {
		if plant.terminalRow == nil && plant.terminalFailure == "" {
			plant.timedOut = true
		}
	}
}

