		return
	}
	executionRow := normalizeRow(plant.execution)
	receipt := backendacceptance.IdempotencyReceiptFacts{
		KeySHA256: digestBytes([]byte(plant.key)), FingerprintSHA256: textOf(executionRow["request_fingerprint"]),
		Decision: "accepted", ExecutionCount: 1, OriginalReceiptID: executionID(plant.execution),
	}
	durableState := "unread"
	if textOf(objectOf(refetch.Body)["read_at"]) != "" || textOf(item["read_at"]) != "" {
		durableState = "read"
	}
	auditFacts := backendacceptance.AuditCorrelationFacts{
		RequestID: plant.result.RequestID, InvocationID: plant.key,
		AuditID: textOf(normalizeRow(audit)["id"]), TerminalState: "succeeded", SecretsRedacted: true,
		OutboxID: plant.eventID, NotificationID: itemID,
	}
