		}
	}
}

func (x *execution) checkRestartTerminal(plant *plantedCase) error {
	switch plant.kind {
	case "notification":
		row, err := x.tableRowByID(notificationEventsTable, plant.eventID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged outbox event " + plant.eventID + " disappeared across the restart"
			return nil
		}
		switch textOf(row["status"]) {
		case "materialized":
			plant.terminalRow, plant.terminalID = row, plant.eventID
		case "failed", "dead_letter":
			plant.terminalFailure = "the staged outbox event " + plant.eventID + " reached terminal state " + textOf(row["status"]) + " instead of materializing exactly once"
		}
	case "export":
		row, err := x.tableRowByID(recordBatchJobTable, plant.jobID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged async export job " + plant.jobID + " disappeared across the restart"
			return nil
		}
		switch textOf(row["status"]) {
		case "completed":
			plant.terminalRow, plant.terminalID = row, plant.jobID
		case "failed", "dead_letter", "cancelled":
			plant.terminalFailure = "the staged async export job " + plant.jobID + " reached terminal state " + textOf(row["status"]) + " instead of resuming to its artifact"
		}
	case "scheduler":
		exists, err := x.env.Database.TableExists(jobRunTable)
		if err != nil || !exists {
			return err
		}
		rows, err := x.env.Database.TableRows(jobRunTable)
		if err != nil {
			return err
		}
		for _, raw := range rows {
			row := normalizeRow(raw)
			id := textOf(row["id"])
			if id == "" || plant.knownRuns[id] || !schedulerRowForDefinition(row, plant.definitionID) {
				continue
			}
			switch textOf(row["status"]) {
			case "succeeded":
				plant.terminalRow, plant.terminalID = row, id
				return nil
			case "failed", "dead_letter":
				plant.terminalFailure = "the due scheduler window run " + id + " reached terminal state " + textOf(row["status"]) + " after the restart"
				return nil
			}
		}
	case "workflow":
		row, err := x.tableRowByID("workflow_process_instances", plant.processID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged workflow process " + plant.processID + " disappeared across the restart"
			return nil
		}
		// Human approval work is intentionally advanced during harvest, after
		// the new Runtime and its fresh participant sessions are established.
		plant.terminalRow, plant.terminalID = row, plant.processID
	case "automation":
		row, err := x.tableRowByID("integration_outbox_messages", plant.eventID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged automation outbox message " + plant.eventID + " disappeared across the restart"
			return nil
		}
		switch textOf(row["status"]) {
		case "sent", "delivered", "read":
			execution, err := x.newAutomationExecution(plant.knownAutomationExecutions, plant.automation, plant.processID)
			if err != nil {
				return err
			}
			if execution != nil {
				state := textOf(normalizeRow(execution)["status"])
				if state == "succeeded" {
					plant.terminalRow, plant.terminalID = row, plant.eventID
				} else if map[string]bool{"failed": true, "blocked": true}[state] {
					plant.terminalFailure = "automation execution reached " + state + " after restart"
				}
			}
		case "failed", "dead_letter", "quarantined":
			plant.terminalFailure = "the staged automation outbox message reached " + textOf(row["status"]) + " after restart"
		}
	}
	return nil
}

