// --- terminal drain ---------------------------------------------------------------

// awaitRestartTerminal waits until every planted case reaches a terminal
// verdict (recovered, failed terminally, or deadline).
func (x *execution) awaitRestartTerminal(plants []*plantedCase) {
	for attempt := 0; attempt < restartTerminalAttempts; attempt++ {
		done := true
		for _, plant := range plants {
			if plant.terminalRow != nil || plant.terminalFailure != "" {
				continue
			}
			if err := x.checkRestartTerminal(plant); err != nil {
				plant.terminalFailure = "database_capture_failed: " + err.Error()
				continue
			}
			if plant.terminalRow == nil && plant.terminalFailure == "" {
				done = false
			}
		}
		if done {
			return
		}
		x.env.sleep(500 * time.Millisecond)
	}
	for _, plant := range plants {
		if plant.terminalRow == nil && plant.terminalFailure == "" {
			plant.timedOut = true
		}
	}
}

func (x *execution) checkRestartTerminal(plant *plantedCase) error {
	switch plant.kind {
	case "notification":
		row, err := x.tableRowByID(notificationEventsTable, plant.eventID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged outbox event " + plant.eventID + " disappeared across the restart"
			return nil
		}
		switch textOf(row["status"]) {
		case "materialized":
			plant.terminalRow, plant.terminalID = row, plant.eventID
		case "failed", "dead_letter":
			plant.terminalFailure = "the staged outbox event " + plant.eventID + " reached terminal state " + textOf(row["status"]) + " instead of materializing exactly once"
		}
	case "export":
		row, err := x.tableRowByID(recordBatchJobTable, plant.jobID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged async export job " + plant.jobID + " disappeared across the restart"
			return nil
		}
		switch textOf(row["status"]) {
		case "completed":
			plant.terminalRow, plant.terminalID = row, plant.jobID
		case "failed", "dead_letter", "cancelled":
			plant.terminalFailure = "the staged async export job " + plant.jobID + " reached terminal state " + textOf(row["status"]) + " instead of resuming to its artifact"
		}
	case "scheduler":
		exists, err := x.env.Database.TableExists(jobRunTable)
		if err != nil || !exists {
			return err
		}
		rows, err := x.env.Database.TableRows(jobRunTable)
		if err != nil {
			return err
		}
		for _, raw := range rows {
			row := normalizeRow(raw)
			id := textOf(row["id"])
			if id == "" || plant.knownRuns[id] || !schedulerRowForDefinition(row, plant.definitionID) {
				continue
			}
			switch textOf(row["status"]) {
			case "succeeded":
				plant.terminalRow, plant.terminalID = row, id
				return nil
			case "failed", "dead_letter":
				plant.terminalFailure = "the due scheduler window run " + id + " reached terminal state " + textOf(row["status"]) + " after the restart"
				return nil
			}
		}
	case "workflow":
		row, err := x.tableRowByID("workflow_process_instances", plant.processID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged workflow process " + plant.processID + " disappeared across the restart"
			return nil
		}
		// Human approval work is intentionally advanced during harvest, after
		// the new Runtime and its fresh participant sessions are established.
		plant.terminalRow, plant.terminalID = row, plant.processID
	case "automation":
		row, err := x.tableRowByID("integration_outbox_messages", plant.eventID)
		if err != nil {
			return err
		}
		if row == nil {
			plant.terminalFailure = "the staged automation outbox message " + plant.eventID + " disappeared across the restart"
			return nil
		}
		switch textOf(row["status"]) {
		case "sent", "delivered", "read":
			execution, err := x.newAutomationExecution(plant.knownAutomationExecutions, plant.automation, plant.processID)
			if err != nil {
				return err
			}
			if execution != nil {
				state := textOf(normalizeRow(execution)["status"])
				if state == "succeeded" {
					plant.terminalRow, plant.terminalID = row, plant.eventID
				} else if map[string]bool{"failed": true, "blocked": true}[state] {
					plant.terminalFailure = "automation execution reached " + state + " after restart"
				}
			}
		case "failed", "dead_letter", "quarantined":
			plant.terminalFailure = "the staged automation outbox message reached " + textOf(row["status"]) + " after restart"
		}
	}
	return nil
}

// --- harvesting -------------------------------------------------------------------

// harvestRestartCase seals one planted case from its post-restart terminal
// facts.
func (x *execution) harvestRestartCase(plant *plantedCase, restartFacts backendacceptance.RuntimeRestartFacts, leases *sync.Map, workerPID int) {
	caseID := plant.acceptanceCase.ID
	if plant.terminalFailure != "" {
		x.fail(caseID, plant.terminalFailure)
		return
	}
	if plant.timedOut || plant.terminalRow == nil {
		x.skip(caseID, "restart_recovery_timeout: the staged work did not reach a terminal state within the post-restart drain deadline")
		return
	}
	restart := observationInput{Kind: "runtime_restart", CapturedFrom: "runtime_process", Facts: restartFacts}
	// A manual Workflow is durable process state resumed by a participant via
	// the public task API. It is deliberately not worker-leased work and its
	// evidence contract therefore contains no worker_terminal observation.
	// Dispatch it before the worker-only lease gate.
	if plant.kind == "workflow" {
		x.harvestWorkflowCase(plant, restart)
		return
	}
	lease := x.harvestLease(plant, leases)
	if lease == "" {
		x.skip(caseID, "worker_lease_unobservable: no transient or durable worker lease/fencing identity was observable for the recovered work")
		return
	}
	switch plant.kind {
	case "notification":
		x.harvestNotificationCase(plant, restart, lease, workerPID)
	case "export":
		x.harvestExportCase(plant, restart, lease, workerPID)
	case "scheduler":
		x.harvestSchedulerCase(plant, restart, lease, workerPID)
	case "automation":
		x.harvestAutomationCase(plant, restart, lease, workerPID)
	}
}

