// harvestLease resolves the worker lease: the transient capture first, then
// the terminal row's durable lease/fencing identity.
func (x *execution) harvestLease(plant *plantedCase, leases *sync.Map) string {
	if value, captured := leases.Load(plant.acceptanceCase.ID); captured {
		if lease := textOf(value); lease != "" {
			return lease
		}
	}
	for _, column := range []string{"lease_owner", "fencing_token", "lease_token"} {
		if lease := textOf(plant.terminalRow[column]); lease != "" {
			return lease
		}
	}
	return ""
}

// rowAttempts derives the worker attempt count from the terminal row.
func rowAttempts(row map[string]any, completedDelta int) int {
	for _, column := range []string{"attempt_count", "attempts", "attempt"} {
		value, exists := row[column]
		if !exists {
			continue
		}
		parsed := intOf(value)
		if parsed < 0 {
			fromText, err := strconv.Atoi(textOf(value))
			if err != nil {
				continue
			}
			parsed = fromText
		}
		if attempts := parsed + completedDelta; attempts >= 1 {
			return attempts
		}
	}
	return 1
}

