DEFAULT_EVENTUAL_READ_TIMEOUT_SECONDS = 3.0
MAX_EVENTUAL_READ_TIMEOUT_SECONDS = 10.0

def _observation_shape(value):
    """Bounded, content-free observation description safe for failure text."""
    if isinstance(value, dict):
        return "dict(%d items)" % len(value)
    if isinstance(value, (list, tuple, set, frozenset)):
        return "%s(%d items)" % (type(value).__name__, len(value))
    if isinstance(value, str):
        return "str(%d chars)" % len(value)
    if isinstance(value, (bytes, bytearray)):
        return "%s(%d bytes)" % (type(value).__name__, len(value))
    return type(value).__name__

def _eventual_read_number(name, value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise HarnessError("%s must be a finite number" % name)
    value = float(value)
    if not math.isfinite(value):
        raise HarnessError("%s must be a finite number" % name)
    return value

def poll_eventual_read(callback, predicate, *,
                       timeout_seconds=DEFAULT_EVENTUAL_READ_TIMEOUT_SECONDS,
                       interval_seconds=0.05, backoff=1.5,
                       max_interval_seconds=0.5, clock=None, sleeper=None):
    """Return the first callback observation accepted by predicate.

    The core owns the monotonic deadline and bounded backoff. Callback,
    predicate, clock, and sleeper exceptions deliberately propagate unchanged.
    """
    if not callable(callback):
        raise HarnessError("eventual read callback must be callable")
    if not callable(predicate):
        raise HarnessError("eventual read predicate must be callable")
    if clock is None:
        clock = time.monotonic
    if sleeper is None:
        sleeper = time.sleep
    if not callable(clock):
        raise HarnessError("eventual read clock must be callable")
    if not callable(sleeper):
        raise HarnessError("eventual read sleeper must be callable")

    timeout_seconds = _eventual_read_number("timeout_seconds", timeout_seconds)
    interval_seconds = _eventual_read_number("interval_seconds", interval_seconds)
    backoff = _eventual_read_number("backoff", backoff)
    max_interval_seconds = _eventual_read_number(
        "max_interval_seconds", max_interval_seconds)
    if timeout_seconds <= 0 or timeout_seconds > MAX_EVENTUAL_READ_TIMEOUT_SECONDS:
        raise HarnessError(
            "timeout_seconds must be greater than zero and at most %.1f" %
            MAX_EVENTUAL_READ_TIMEOUT_SECONDS)
    if interval_seconds <= 0 or interval_seconds > timeout_seconds:
        raise HarnessError(
            "interval_seconds must be greater than zero and at most timeout_seconds")
    if backoff < 1.0:
        raise HarnessError("backoff must be at least 1.0")
    if (max_interval_seconds < interval_seconds or
            max_interval_seconds > timeout_seconds):
        raise HarnessError(
            "max_interval_seconds must be between interval_seconds and timeout_seconds")

    started = _eventual_read_number("clock result", clock())
    deadline = started + timeout_seconds
    now = started
    delay = interval_seconds
    attempts = 0
    last_observation = None
    while True:
        if attempts and now >= deadline:
            raise EventualReadTimeout(timeout_seconds, attempts, last_observation)
        last_observation = callback()
        attempts += 1
        if predicate(last_observation):
            return last_observation
        observed_at = _eventual_read_number("clock result", clock())
        if observed_at < now:
            raise HarnessError("eventual read clock must be monotonic")
        now = observed_at
        if now >= deadline:
            raise EventualReadTimeout(timeout_seconds, attempts, last_observation)
        sleeper(min(delay, deadline - now))
        slept_until = _eventual_read_number("clock result", clock())
        if slept_until < now:
            raise HarnessError("eventual read clock must be monotonic")
        now = slept_until
        delay = min(delay * backoff, max_interval_seconds)

