// Package acceptancefailure carries authenticated development-only acceptance
// markers from HTTP transports to application owners. Transports authenticate
// requests before setting a marker; application services never inspect headers
// or ambient secrets themselves.
package acceptancefailure

import "context"

const ErrorCode = "backend.acceptance.injected_failure"

type beforeCommitContextKey struct{}

type forceAsyncExportContextKey struct{}

func WithBeforeCommit(ctx context.Context) context.Context {
	return context.WithValue(ctx, beforeCommitContextKey{}, true)
}

func BeforeCommit(ctx context.Context) bool {
	injected, _ := ctx.Value(beforeCommitContextKey{}).(bool)
	return injected
}

// WithForceAsyncExport marks one authenticated acceptance export prepare for
// the asynchronous worker substrate even when its real authorized row count is
// at or below the production routing threshold. Only an HTTP transport that
// has authenticated the managed Runtime's acceptance secret may set it.
func WithForceAsyncExport(ctx context.Context) context.Context {
	return context.WithValue(ctx, forceAsyncExportContextKey{}, true)
}

// ForceAsyncExport reports whether the authenticated acceptance-only routing
// marker is present.
func ForceAsyncExport(ctx context.Context) bool {
	forced, _ := ctx.Value(forceAsyncExportContextKey{}).(bool)
