// acceptanceForceAsyncExportRequest authenticates the acceptance runner's
// development-only routing signal. Missing or invalid credentials and every
// production request remain byte-for-byte on the normal threshold path.
func acceptanceForceAsyncExportRequest(r *http.Request) *http.Request {
	presented := strings.TrimSpace(r.Header.Get(acceptanceForceAsyncExportHeader))
