EAST_CASE = "action_lead.request_lead_conversion.sales_rep.audit_correlation"
NORTH_CASE = "action_lead.request_lead_conversion.sales_rep.success"


def _session(harness, case_id):
    return harness.session_for_case(harness.denominator.case(case_id))


def _output(exchange):
    return (exchange.body or {}).get("output") or {}


def _require_success(exchange):
    return core.ReasonOracle.success(exchange, statuses=(200,), require_non_empty=True)


def _action(harness, session, path, data, key):
    return harness.runtime.request(
        "POST", path, session=session, body={"data": data}, idempotency_key=key)


class _HeaderInjector(urllib.request.BaseHandler):
    def __init__(self, headers):
        self.headers = headers

    def http_request(self, request):
        for key, value in self.headers.items():
            request.add_unredirected_header(key, value)
        return request

    https_request = http_request


@contextlib.contextmanager
def _request_headers(headers):
    previous = urllib.request._opener
    urllib.request.install_opener(urllib.request.build_opener(_HeaderInjector(headers)))
    try:
        yield
    finally:
        urllib.request.install_opener(previous)


def _acceptance_secret(harness):
    path = os.path.join(PROJECT_ROOT, ".domainry", "builder", "runtime",
                        "acceptance-failure-secret")
    with open(path, "r", encoding="utf-8") as handle:
        secret = handle.read().strip()
    if not secret:
        raise core.HarnessError("managed Runtime acceptance failure secret is unavailable")
    harness.sessions._mark_sensitive(secret)
    return secret


def _get_record(harness, session, object_key, record_id):
    exchange = harness.runtime.request(
        "GET", "/objects/%s/records/%s" % (object_key, record_id), session=session)
    _require_success(exchange)
    return exchange


def _execution(harness, key):
    rows = harness.database.query(
        "SELECT id, request_fingerprint, status, response_status, error_code "
        "FROM %s WHERE workspace_id=%%s AND idempotency_key=%%s "
        "ORDER BY created_at DESC LIMIT 1" %
        harness.database.relation("business_action_executions"), ("default", key))
    if len(rows) != 1:
        raise core.HarnessError("business action execution receipt is unavailable")
    return rows[0]


def _rows_for_fixture(harness, fixture):
    state = {}
    lead_id = fixture.get("lead_id", "")
    approval_id = fixture.get("approval_id", "")
    if lead_id:
        state["lead"] = harness.database.query(
            "SELECT * FROM %s WHERE workspace_id=%%s AND id=%%s" %
            harness.database.relation("lead"), ("default", lead_id))
        state["conversion_approval"] = harness.database.query(
            "SELECT * FROM %s WHERE workspace_id=%%s AND lead_id=%%s ORDER BY id" %
            harness.database.relation("conversion_approval"),
            ("default", lead_id))
        state["customer"] = harness.database.query(
            "SELECT * FROM %s WHERE workspace_id=%%s AND source_lead_id=%%s ORDER BY id" %
            harness.database.relation("customer"),
            ("default", lead_id))
    elif approval_id:
        state["conversion_approval"] = harness.database.query(
            "SELECT * FROM %s WHERE workspace_id=%%s AND id=%%s" %
            harness.database.relation("conversion_approval"),
            ("default", approval_id))
    return state


def _snapshot(harness, fixture):
    return core.sha256_json(_rows_for_fixture(harness, fixture))


def _create_qualified_lead(harness, actor_case_id, namespace, amount="90000.00"):
    session = _session(harness, actor_case_id)
    create_key = namespace + "-create"
    exchange = _action(
        harness, session, "/objects/lead/actions/lead.create_lead/run",
        {"request_id": create_key, "company_name": "Acceptance " + namespace,
         "expected_amount": amount, "source": "referral"}, create_key)
    _require_success(exchange)
    lead_id = _output(exchange).get("lead_id", "")
    if not lead_id:
        raise core.HarnessError("lead creation returned no lead identity")
    for action_key in ("lead.mark_lead_contacted", "lead.mark_lead_qualified"):
        current = _get_record(harness, session, "lead", lead_id)
        transition_key = namespace + "-" + action_key.rsplit(".", 1)[1]
        exchange = _action(
            harness, session,
            "/objects/lead/records/%s/actions/%s" % (lead_id, action_key),
            {"request_id": transition_key,
             "expected_updated_at": current.body["updated_at"]}, transition_key)
        _require_success(exchange)
    current = _get_record(harness, session, "lead", lead_id)
    return {"lead_id": lead_id, "session": session,
            "updated_at": current.body["updated_at"], "namespace": namespace}


