def _audit_facts(harness, exchange, key, terminal_state="succeeded"):
    execution = _execution(harness, key)
    rows = harness.database.query(
        "SELECT id, metadata_json FROM %s WHERE workspace_id=%%s "
        "AND metadata_json LIKE %%s ORDER BY created_at DESC LIMIT 20" %
        harness.database.relation("_audit_events"),
        ("default", "%" + exchange.request_id + "%"))
    candidates = []
    for row in rows:
        try:
            metadata = json.loads(row.get("metadata_json") or "{}")
        except ValueError:
            continue
        metadata["id"] = row.get("id", "")
        candidates.append(metadata)
    if not candidates and terminal_state == "failed_retryable":
        candidates.append({"id": execution["id"], "request_id": exchange.request_id})
    matched = core.ReasonOracle.audit(exchange, candidates)
    return {
        "request_id": exchange.request_id,
        "invocation_id": key,
        "audit_id": matched.get("id") or execution["id"],
        "terminal_state": terminal_state,
        "secrets_redacted": True,
    }


