func (a *ReportRecordAdapter) CanPushdownReportDataset(_ context.Context, principal identitymodel.Principal, objects []definitionmodel.ObjectSchema) bool {
	for _, object := range objects {
		for _, field := range object.Fields {
			if !recordpolicy.RecordCanReadField(principal.Role, object.Key, field.Key) || recordpolicy.RecordFieldReadMasked(principal.Role, object.Key, field.Key) {
				return false
			}
		}
		for _, permission := range principal.Role.FieldPermissions {
			if permission.ObjectKey == object.Key && len(permission.Policies) > 0 {
				return false
			}
		}
	}
	return true
}

func (a *ReportRecordAdapter) AuthorizeReportExportField(_ context.Context, principal identitymodel.Principal, objectKey, fieldKey string) (bool, error) {
	object, err := a.application.ObjectForAction(principal, objectKey, "export")
	if err != nil {
		return false, err
	}
	if fieldKey == "id" || fieldKey == "created_at" || fieldKey == "updated_at" {
		if !recordpolicy.RecordCanExportField(principal.Role, object.Key, fieldKey) {
			return false, &apperror.AppError{Kind: apperror.KindForbidden, Code: "backend.report.export_field_denied"}
		}
		return recordpolicy.RecordFieldExportMasked(principal.Role, object.Key, fieldKey), nil
	}
	for _, field := range object.Fields {
		if field.Key != fieldKey || field.DisabledAt != "" {
			continue
		}
		if !recordpolicy.RecordCanExportObjectField(principal.Role, object, field) {
			return false, &apperror.AppError{Kind: apperror.KindForbidden, Code: "backend.report.export_field_denied"}
		}
		return recordpolicy.RecordFieldExportMasked(principal.Role, object.Key, field.Key), nil
	}
	return false, &apperror.AppError{Kind: apperror.KindBadRequest, Code: "backend.report.export_field_not_found"}
}

