func recordFieldRequiresExplicitAccess(object definitionmodel.ObjectSchema, field definitionmodel.FieldSchema) bool {
	if strings.TrimSpace(fmt.Sprint(object.Config["field_access_mode"])) == "default_deny" {
		return true
	}
	if sensitive, ok := field.Config["sensitive"].(bool); ok && sensitive {
		return true
	}
	switch strings.TrimSpace(fmt.Sprint(field.Config["sensitivity"])) {
	case "sensitive", "secret", "credential", "security_raw", "key_material":
		return true
	default:
		return false
	}
}

func recordObjectField(object definitionmodel.ObjectSchema, key string) (definitionmodel.FieldSchema, bool) {
	for _, field := range object.Fields {
		if field.Key == key && field.DisabledAt == "" {
			return field, true
		}
	}
	return definitionmodel.FieldSchema{}, false
}

