func RecordFieldExportMasked(role identitymodel.RoleSchema, objectKey, fieldKey string) bool {
	if identitycontract.IdentityRoleAllows(role, "workspace", "admin") {
		return false
	}
	foundReadable := false
	for _, permission := range role.FieldPermissions {
		if permission.ObjectKey == objectKey && permission.FieldKey == fieldKey {
			if !permission.Export {
				continue
			}
			foundReadable = true
			if !permission.Masked {
				return false
			}
		}
	}
	return foundReadable
}

